function normalizePlayerName(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]/g, "");
}


let comparisonData = {};
let comparisonLoaded = false;

const rankingSourceLabels = [
  ['flock', 'Flock Fantasy Rank'],
  ['espn', 'ESPN Rank'],
  ['yahoo', 'Yahoo Rank'],
  ['fantasypros', 'FantasyPros Rank'],
  ['draftsharks', 'DraftSharks Rank']
];

function numericRank(value) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function sourceRanksForPlayer(player) {
  const key = normalizePlayerName(player && player.player);
  const saved = comparisonData[key] || {};
  const flock = flockData[key];
  return {
    flock: flock ? numericRank(flock.rank) : null,
    espn: numericRank(saved.espn),
    yahoo: numericRank(saved.yahoo),
    fantasypros: numericRank(saved.fantasypros),
    draftsharks: numericRank(saved.draftsharks)
  };
}

function averageRank(values) {
  const nums = values.map(numericRank).filter(Boolean);
  if (!nums.length) return null;
  return Math.round(nums.reduce((a,b) => a+b, 0) / nums.length);
}

function comparisonSummary(player) {
  const ranks = sourceRanksForPlayer(player);
  const sourceValues = rankingSourceLabels.map(item => ranks[item[0]]).filter(Boolean);
  return {
    ranks: ranks,
    consensus: averageRank(sourceValues),
    flockRank: ranks.flock,
    high: sourceValues.length ? Math.min.apply(null, sourceValues) : null,
    low: sourceValues.length ? Math.max.apply(null, sourceValues) : null,
    sourceCount: sourceValues.length
  };
}

function formatRank(value) {
  const n = numericRank(value);
  if (!n) return 'N/A';
  return '#' + (Number.isInteger(n) ? n : n.toFixed(1));
}

function consensusDiffHTML(myRank, consensus) {
  if (!consensus) return '<span class="consensus-diff same">N/A</span>';
  const delta = Math.round((consensus - myRank) * 10) / 10;
  if (Math.abs(delta) < .05) return '<span class="consensus-diff same">EVEN</span>';
  const cls = delta > 0 ? 'higher' : 'lower';
  const sign = delta > 0 ? '+' : '−';
  return '<span class="consensus-diff '+cls+'">'+sign+Math.abs(delta).toFixed(Number.isInteger(Math.abs(delta)) ? 0 : 1)+'</span>';
}

function renderSourceComparison(player, myRank) {
  const summary = comparisonSummary(player);
  const consensusEl = document.getElementById('cardConsensusRank');
  const flockEl = document.getElementById('cardFlockRank');
  if (consensusEl) consensusEl.textContent = formatRank(summary.consensus);
  if (flockEl) flockEl.textContent = formatRank(summary.flockRank);

  const diff = document.getElementById('cardDifference');
  if (diff) {
    if (!summary.consensus) {
      diff.textContent = comparisonLoaded
        ? 'No outside ranking is available for this player yet.'
        : 'Ranking sources are loading…';
    } else if (Math.abs(myRank - summary.consensus) < .05) {
      diff.textContent = 'Football HQ is right in line with expert consensus.';
    } else if (myRank < summary.consensus) {
      const n = Math.round((summary.consensus - myRank) * 10) / 10;
      diff.textContent = '🔥 Football HQ is ' + n + ' spot' + (n === 1 ? '' : 's') + ' HIGHER than expert consensus';
    } else {
      const n = Math.round((myRank - summary.consensus) * 10) / 10;
      diff.textContent = '⚠️ Football HQ is ' + n + ' spot' + (n === 1 ? '' : 's') + ' LOWER than expert consensus';
    }
  }

  const rows = [];
  rows.push('<div class="source-rank-row my-rank-source"><span class="source-rank-name">Football HQ Rank</span><span class="source-rank-number">#'+myRank+'</span></div>');
  ['espn', 'yahoo', 'fantasypros', 'draftsharks'].forEach(function(key) {
    const item = rankingSourceLabels.find(function(source) { return source[0] === key; });
    if (!item) return;
    const value = summary.ranks[key];
    const valueText = value ? formatRank(value) : (comparisonLoaded ? 'Not available' : 'Loading…');
    const unavailableClass = value ? '' : ' source-unavailable';
    rows.push('<div class="source-rank-row'+unavailableClass+'"><span class="source-rank-name">'+item[1]+'</span><span class="source-rank-number">'+valueText+'</span></div>');
  });
  const flockItem = rankingSourceLabels.find(function(source) { return source[0] === 'flock'; });
  const flockValue = summary.ranks.flock;
  const flockValueText = flockValue ? formatRank(flockValue) : (comparisonLoaded ? 'Not available' : 'Loading…');
  const flockUnavailableClass = flockValue ? '' : ' source-unavailable';
  rows.push('<div class="source-rank-row'+flockUnavailableClass+'"><span class="source-rank-name">'+(flockItem ? flockItem[1] : 'Flock Fantasy Rank')+'</span><span class="source-rank-number">'+flockValueText+'</span></div>');
  const grid = document.getElementById('sourceRankingsGrid');
  if (grid) grid.innerHTML = rows.join('');

  const coverage = [];
  coverage.push(summary.sourceCount + ' of ' + rankingSourceLabels.length + ' ranking sources');
  if (summary.high && summary.low) coverage.push('range ' + formatRank(summary.high) + '–' + formatRank(summary.low));
  const coverageEl = document.getElementById('comparisonCoverage');
  if (coverageEl) coverageEl.textContent = coverage.join(' • ');
}


let fhqTop500Extended=false;
let fhqTop500RetryTimer=null;
function buildConsensusExtensionCandidates(){
  const existing=new Set((players||[]).slice(0,250).map(p=>normalizePlayerName(p.player))),candidates=[];
  const active=(typeof sleeperPlayersByName!=='undefined'?Object.values(sleeperPlayersByName):[]);
  active.forEach(function(s){
    const name=s&&s.name?String(s.name):'',pos=String((s&&s.position)||'').toUpperCase(),team=String((s&&s.team)||'').toUpperCase();
    if(!name||existing.has(normalizePlayerName(name))||!['QB','RB','WR','TE'].includes(pos)||!team)return;
    const key=normalizePlayerName(name),saved=(typeof comparisonData!=='undefined'&&comparisonData[key])||{},flock=(typeof flockData!=='undefined'&&flockData[key])||{};
    const ranks=[numericRank(flock.rank),numericRank(saved.espn),numericRank(saved.yahoo),numericRank(saved.fantasypros),numericRank(saved.draftsharks)].filter(Boolean);
    const consensus=ranks.length?ranks.reduce((a,b)=>a+b,0)/ranks.length:null;
    const depthRaw=Number(s.depth_chart_order),depth=Number.isFinite(depthRaw)&&depthRaw>0?depthRaw:8;
    const exp=Number(s.years_exp)||0;
    const posPenalty={RB:0,WR:6,TE:18,QB:24}[pos]||30;
    /* Source ranks lead. Depth + experience are fallback ordering only. */
    const fallback=900+(depth*32)+posPenalty-Math.min(exp,8)*2;
    candidates.push({player:name,position:pos,team:team,tier:'',notes:'Consensus extension',
      _score:consensus||fallback,_sourceCount:ranks.length,_depth:depth});
  });
  return candidates.sort(function(a,b){
    return (b._sourceCount-a._sourceCount)||(a._score-b._score)||(a._depth-b._depth)||a.player.localeCompare(b.player);
  });
}
function extendRankingsTo500(){
  if(!Array.isArray(players)||!players.length)return false;
  const originalTop=players.slice(0,250);
  const extension=buildConsensusExtensionCandidates().slice(0,250);
  extension.forEach(p=>{delete p._score;delete p._sourceCount;delete p._depth;});
  players=originalTop.concat(extension);
  fhqTop500Extended=players.length>=500;
  if(sitePage==='rankings'||sitePage==='draft')renderPlayers((document.getElementById('searchInput')||{}).value||'');
  runFootballHQDatabaseIntegrity();
  return fhqTop500Extended;
}
function scheduleTop500Extension(delay){
  clearTimeout(fhqTop500RetryTimer);
  fhqTop500RetryTimer=setTimeout(function(){
    Promise.resolve(typeof loadSleeperPlayers==='function'?loadSleeperPlayers():null).then(function(){
      if(!extendRankingsTo500()){
        /* Sleeper may still be loading through Apps Script. Retry without blocking the UI. */
        fhqTop500RetryTimer=setTimeout(function(){extendRankingsTo500();},1200);
      }
    }).catch(function(e){console.warn('Top-500 extension unavailable',e);});
  },Number(delay)||0);
}


function runFootballHQDatabaseIntegrity(){
  try{
    const rankingList=Array.isArray(players)?players:[];
    const names=rankingList.map(p=>normalizePlayerName(p&&p.player)).filter(Boolean);
    const duplicates=names.filter((n,i)=>names.indexOf(n)!==i);
    const missingFields=rankingList.filter(p=>!p||!p.player||!p.position||!p.team).map(p=>p&&p.player||'(blank)');
    const legendPool=(typeof legendGuessPool==='function'?legendGuessPool():[]);
    const legendNames=new Set(),legendDup=[];
    legendPool.forEach(function(p){const k=normalizePlayerName(p&&p.name);if(!k)return;if(legendNames.has(k))legendDup.push(p.name);legendNames.add(k);});
    const report={
      at:new Date().toISOString(),
      rankingCount:rankingList.length,
      top500Ready:rankingList.length>=500,
      rankingDuplicates:Array.from(new Set(duplicates)),
      missingRankingFields:missingFields,
      legendCount:legendPool.length,
      legendDuplicates:Array.from(new Set(legendDup)),
      dailyDate:typeof dailyDateKey==='function'?dailyDateKey():'',
      passed:rankingList.length>=500&&!duplicates.length&&!missingFields.length
    };
    if(typeof window!=='undefined')window.FHQ_DATABASE_HEALTH=report;
    try{localStorage.setItem('footballHQDatabaseHealthV1',JSON.stringify(report))}catch(e){}
    if(report.passed)console.info('Football HQ database integrity: PASS',report);
    else console.warn('Football HQ database integrity: REVIEW',report);
    return report;
  }catch(e){console.warn('Football HQ integrity test failed',e);return null}
}
if(typeof window!=='undefined')window.runFootballHQDatabaseIntegrity=runFootballHQDatabaseIntegrity;

function loadComparisonRankings() {
  google.script.run
    .withSuccessHandler(function(data) {
      comparisonData = data || {};
      comparisonLoaded = true;
      renderPlayers((document.getElementById('searchInput') || {}).value || '');
      const modal = document.getElementById('playerModal');
      if (modal && modal.classList.contains('open') && typeof currentCardIndex === 'number') {
        const p = players[currentCardIndex];
        if (p) renderSourceComparison(p, currentCardIndex + 1);
      }
    })
    .withFailureHandler(function(error) {
      comparisonData = {};
      comparisonLoaded = false;
      console.warn('Comparison rankings could not be loaded.', error);
    })
    .getComparisonRankings();
}

function getPositionRankForIndex(index) {
  const ranks = calculatePositionRanks();
  return ranks[index] || "";
}


function normalizeRisk(value) {
  const v = String(value || "").trim().toLowerCase().replace(/[_-]+/g," ").replace(/\s+/g," ");
  if (v === "very high") return "very high";
  if (v === "high") return "high";
  if (v === "moderate" || v === "medium") return "moderate";
  if (v === "low") return "low";
  if (v === "very low") return "very low";
  return "";
}
function riskClass(value) {
  const r = normalizeRisk(value);
  return r ? "risk-" + r.replace(" ","-") : "risk-unset";
}
function riskLabel(value) {
  const r = normalizeRisk(value);
  if (!r) return "Not rated";
  return r.split(" ").map(w => w.charAt(0).toUpperCase()+w.slice(1)).join(" ");
}
function riskSelectHTML(index, current) {
  const opts = ["","Very High","High","Moderate","Low","Very Low"];
  const cur = riskLabel(current);
  return '<select class="risk-select" data-risk-index="'+index+'">' +
    opts.map(o => '<option value="'+o+'"'+((o===cur || (!o && cur==="Not rated"))?' selected':'')+'>'+(o||"Not rated")+'</option>').join("") +
    '</select>';
}
function updateRiskMeter(value) {
  const r = normalizeRisk(value);
  const ids = {"very high":"riskSegVH","high":"riskSegH","moderate":"riskSegM","low":"riskSegL","very low":"riskSegVL"};
  ["riskSegVH","riskSegH","riskSegM","riskSegL","riskSegVL"].forEach(id => document.getElementById(id).classList.remove("active"));
  if (ids[r]) document.getElementById(ids[r]).classList.add("active");
  const label = document.getElementById("cardRiskLabel");
  label.textContent = riskLabel(value);
  label.className = "risk-meter-label " + riskClass(value);
}


let ALL_STATS_2025 = {};
let statsLoaded = false;
let statsLoadFailed = false;

function setStatBox(n, label, value) {
  document.getElementById("stat"+n+"Label").textContent = label;
  document.getElementById("stat"+n+"Value").textContent =
    (value === null || value === undefined || value === "") ? "—" : value;
}


function firstStatValue(obj, keys) {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null && obj[key] !== "") {
      return obj[key];
    }
  }
  return null;
}

function updatePlayerStats(player) {
  const pos = String(player.position || "").toUpperCase();
  const key = normalizePlayerName(player.player);
  const s = ALL_STATS_2025[key];

  if (!statsLoaded && !statsLoadFailed) {
    const labels = pos === "QB"
      ? ["PASS YDS","PASS TD","INT","RUSH YDS","RUSH TD","GAMES"]
      : (pos === "WR" || pos === "TE")
        ? ["REC","REC YDS","REC TD","TARGETS","YDS/REC","GAMES"]
        : ["RUSH YDS","RUSH TD","REC","REC YDS","REC TD","GAMES"];

    labels.forEach((label, i) => setStatBox(i + 1, label, null));
    document.getElementById("playerStatsNote").textContent = "Loading 2025 stats…";
    return;
  }

  if (!s) {
    const labels = pos === "QB"
      ? ["PASS YDS","PASS TD","INT","RUSH YDS","RUSH TD","GAMES"]
      : (pos === "WR" || pos === "TE")
        ? ["REC","REC YDS","REC TD","TARGETS","YDS/REC","GAMES"]
        : ["RUSH YDS","RUSH TD","REC","REC YDS","REC TD","GAMES"];

    labels.forEach((label, i) => setStatBox(i + 1, label, null));
    document.getElementById("playerStatsNote").textContent =
      statsLoadFailed ? "2025 stats unavailable right now" : "No 2025 NFL stats found";
    return;
  }

  if (pos === "QB") {
    setStatBox(1,"PASS YDS",s.passYds);
    setStatBox(2,"PASS TD",s.passTD);
    setStatBox(3,"INT", firstStatValue(s, [
      "interceptions",
      "interceptionsThrown",
      "passingInterceptions",
      "passInterceptions",
      "passINT",
      "passInts",
      "ints",
      "int"
    ]));
    setStatBox(4,"RUSH YDS",s.rushYds);
    setStatBox(5,"RUSH TD",s.rushTD);
    setStatBox(6,"GAMES",s.games);
  } else if (pos === "WR" || pos === "TE") {
    setStatBox(1,"REC",s.receptions);
    setStatBox(2,"REC YDS",s.recYds);
    setStatBox(3,"REC TD",s.recTD);
    setStatBox(4,"TARGETS",s.targets);
    setStatBox(5,"YDS/REC",
      (s.receptions && s.recYds !== null && s.recYds !== undefined)
        ? (Number(s.recYds) / Number(s.receptions)).toFixed(1)
        : null);
    setStatBox(6,"GAMES",s.games);
  } else {
    setStatBox(1,"RUSH YDS",s.rushYds);
    setStatBox(2,"RUSH TD",s.rushTD);
    setStatBox(3,"REC",s.receptions);
    setStatBox(4,"REC YDS",s.recYds);
    setStatBox(5,"REC TD",s.recTD);
    setStatBox(6,"GAMES",s.games);
  }

  document.getElementById("playerStatsNote").textContent = "2025 regular season";
}

function loadAll2025Stats() {
  google.script.run
    .withSuccessHandler(function(data) {
      ALL_STATS_2025 = data || {};
      statsLoaded = true;
      statsLoadFailed = false;

      const modal = document.getElementById("playerModal");
      if (modal && modal.classList.contains("open") && typeof currentCardIndex === "number") {
        const currentPlayer = players[currentCardIndex];
        if (currentPlayer) updatePlayerStats(currentPlayer);
      }
    })
    .withFailureHandler(function() {
      statsLoaded = false;
      statsLoadFailed = true;
    })
    .getAll2025Stats();
}

let currentCardIndex = null;


let sleeperPlayersByName = {};
let sleeperPlayersLoaded = false;
let sleeperPlayersLoading = false;

function playerPhotoSlug(name) {
  return String(name || "")
    .toLowerCase()
    .replace(/[.'’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

async function loadSleeperPlayers() {
  if (sleeperPlayersLoaded || sleeperPlayersLoading) return;
  sleeperPlayersLoading = true;

  try {
    const response = await fetch("https://api.sleeper.app/v1/players/nfl?active=true");
    if (!response.ok) throw new Error("Sleeper player lookup failed");

    const data = await response.json();
    const lookup = {};

    Object.keys(data || {}).forEach(playerId => {
      const item = data[playerId] || {};
      const fullName = item.full_name || [item.first_name, item.last_name].filter(Boolean).join(" ");
      if (!fullName) return;

      const key = normalizePlayerName(fullName);
      if (!key) return;

      lookup[key] = {
        id: playerId,
        name: fullName,
        age: item.age || "",
        team: item.team || "",
        position: item.position || "",
        fantasy_positions: item.fantasy_positions || [],
        years_exp: item.years_exp == null ? "" : item.years_exp,
        status: item.status || "",
        depth_chart_position: item.depth_chart_position || "",
        depth_chart_order: item.depth_chart_order == null ? null : Number(item.depth_chart_order),
        college: item.college || "",
        draft_round: item.draft_round == null ? "" : String(item.draft_round),
        draft_year: item.draft_year == null ? "" : String(item.draft_year),
        jersey_number: item.number == null ? "" : String(item.number)
      };
    });

    sleeperPlayersByName = lookup;
    sleeperPlayersLoaded = true;
  } catch (e) {
    console.warn("Could not load Sleeper player IDs for photo fallback.", e);
  } finally {
    sleeperPlayersLoading = false;
  }
}


const nflByeWeeks2026 = {
  CAR:5, KC:5,
  CIN:6, DET:6, MIA:6, MIN:6,
  BUF:7, JAX:7, LAC:7, WAS:7,
  HOU:8, NO:8, NYG:8, SF:8,
  PIT:9, TEN:9,
  CHI:10, DEN:10, PHI:10, TB:10,
  ATL:11, CLE:11, GB:11, LAR:11, NE:11, SEA:11,
  BAL:13, IND:13, LV:13, NYJ:13,
  ARI:14, DAL:14
};

function updatePlayerMeta(player) {
  const el = document.getElementById("cardPlayerMeta");
  if (!el || !player) return;

  const key = normalizePlayerName(player.player);
  const sleeper = sleeperPlayersByName[key] || {};
  const parts = [];

  if (sleeper.age) parts.push("Age " + sleeper.age);

  const team = String(player.team || sleeper.team || "").toUpperCase();
  const bye = nflByeWeeks2026[team];
  if (bye) parts.push("Bye Week " + bye);

  el.textContent = parts.join(" • ");

  // If player data is still loading, refresh this line once it arrives.
  if (!sleeperPlayersLoaded) {
    loadSleeperPlayers().then(function() {
      if (typeof currentCardIndex !== "number") return;
      const currentPlayer = players[currentCardIndex];
      if (!currentPlayer) return;
      if (normalizePlayerName(currentPlayer.player) !== key) return;
      updatePlayerMeta(currentPlayer);
    });
  }
}


function fhqSilhouetteDataUri(name){
  const initials=(String(name||'?').trim().split(/\s+/).slice(0,2).map(x=>x.charAt(0).toUpperCase()).join('')||'?');
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240" viewBox="0 0 240 240"><rect width="240" height="240" rx="28" fill="#202a31"/><circle cx="120" cy="82" r="44" fill="#80909b"/><path d="M42 220c8-52 38-80 78-80s70 28 78 80" fill="#80909b"/><text x="120" y="227" text-anchor="middle" font-family="Arial" font-size="18" font-weight="700" fill="#d9e2e7">'+initials+'</text></svg>';
  return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg);
}
function playerPhotoCandidates(name){
  const key=normalizePlayerName(name),out=[];
  const direct=(typeof flockPhotos!=='undefined'&&flockPhotos[key])||'';if(direct)out.push(direct);
  const s=(typeof sleeperPlayersByName!=='undefined'&&sleeperPlayersByName[key])||null;
  if(s&&s.id){
    out.push('https://sleepercdn.com/content/nfl/players/'+encodeURIComponent(s.id)+'.jpg');
    out.push('https://flock-yearly-player-images.s3.us-east-2.amazonaws.com/2025/'+encodeURIComponent(s.id)+'_'+encodeURIComponent(playerPhotoSlug(name))+'.webp');
  }
  if(s&&s.espn_id)out.push('https://a.espncdn.com/i/headshots/nfl/players/full/'+encodeURIComponent(s.espn_id)+'.png');
  return Array.from(new Set(out.filter(Boolean)));
}
const fhqWikiPhotoMemory={};
function fhqWikipediaCacheKey(name){return 'fhqWikiPhoto:'+normalizePlayerName(name)}
function fhqTryWikipediaPhoto(img,name){
  if(!img||!name)return;
  const key=normalizePlayerName(name);
  const cached=fhqWikiPhotoMemory[key]||(()=>{try{return localStorage.getItem(fhqWikipediaCacheKey(name))||''}catch(e){return ''}})();
  if(cached){
    img.classList.remove('fhq-photo-resolving');img.classList.add('fhq-photo-ready');
    img.onerror=function(){img.onerror=null;img.src=fhqSilhouetteDataUri(name)};
    img.src=cached;return;
  }
  if(img.dataset.fhqWikiTried==='1'){img.classList.remove('fhq-photo-resolving');img.src=fhqSilhouetteDataUri(name);return;}
  img.dataset.fhqWikiTried='1';img.classList.add('fhq-photo-resolving');
  const q=encodeURIComponent(String(name)+' NFL football');
  fetch('https://en.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch='+q+'&gsrlimit=5&prop=pageimages&piprop=thumbnail&pithumbsize=500&format=json&origin=*')
    .then(r=>r.ok?r.json():Promise.reject(new Error('wiki')))
    .then(function(data){
      const pages=data&&data.query&&data.query.pages?Object.values(data.query.pages):[];
      const page=pages.find(p=>p&&p.thumbnail&&p.thumbnail.source);
      if(!page)throw new Error('no photo');
      const url=page.thumbnail.source;fhqWikiPhotoMemory[key]=url;
      try{localStorage.setItem(fhqWikipediaCacheKey(name),url)}catch(e){}
      img.classList.remove('fhq-photo-resolving');img.classList.add('fhq-photo-ready');
      img.onerror=function(){img.onerror=null;img.src=fhqSilhouetteDataUri(name)};
      img.src=url;
    })
    .catch(function(){
      img.classList.remove('fhq-photo-resolving');
      img.onerror=null;img.src=fhqSilhouetteDataUri(name);
    });
}
function fhqPhotoOnError(img){
  try{
    const list=JSON.parse(decodeURIComponent(img.dataset.fhqCandidates||'%5B%5D'));
    const idx=Number(img.dataset.fhqIndex||0)+1;
    if(idx<list.length){img.dataset.fhqIndex=idx;img.src=list[idx];return;}
    fhqTryWikipediaPhoto(img,img.dataset.fhqName||img.alt||'NFL player');
  }catch(e){fhqTryWikipediaPhoto(img,img.dataset.fhqName||img.alt||'NFL player');}
}
function guaranteedPlayerImgHTML(name,className,alt){
  const list=playerPhotoCandidates(name),encoded=encodeURIComponent(JSON.stringify(list));
  const src=list[0]||fhqSilhouetteDataUri(name);
  const wikiKick=list.length?'':' onload="fhqTryWikipediaPhoto(this,'+JSON.stringify(String(name)).replace(/"/g,'&quot;')+')"';
  return '<img class="'+escapeHTML(className||'player-photo')+'" src="'+escapeHTML(src)+'" alt="'+escapeHTML(alt||name||'Player')+
    '" loading="lazy" data-fhq-name="'+escapeHTML(name)+'" data-fhq-index="0" data-fhq-candidates="'+encoded+
    '" onerror="fhqPhotoOnError(this)"'+wikiKick+'>';
}

function fallbackPlayerPhotoUrl(playerName) {
  const key = normalizePlayerName(playerName);
  const sleeper = sleeperPlayersByName[key];
  if (!sleeper || !sleeper.id) return "";

  const slug = playerPhotoSlug(playerName);
  return "https://flock-yearly-player-images.s3.us-east-2.amazonaws.com/2025/" +
    encodeURIComponent(sleeper.id) + "_" + encodeURIComponent(slug) + ".webp";
}

function playerPhotoPlaceholderHTML(playerName) {
  const initial = escapeHTML((playerName || "?").charAt(0).toUpperCase());
  return '<div class="player-photo-placeholder">' + initial + '</div>';
}

function draftedPlayerPhotoHTML(player, className) {
  if(!player)return '';
  const name=player.player||player.name||'Player';
  return guaranteedPlayerImgHTML(name,className||'draft-player-photo-sm',name);
}

function renderPlayerPhoto(player) {
  const wrap=document.getElementById("cardPhotoWrap");
  if(!wrap||!player)return;
  wrap.innerHTML=guaranteedPlayerImgHTML(player.player,'player-photo',player.player);
}

function openPlayerCard(index) {
  if (isEditorMode) return;
  currentCardIndex = index;
  const p = players[index];
  if (!p) return;

  const myRank = index + 1;
  const posRank = getPositionRankForIndex(index);

  document.getElementById("cardPlayerName").textContent = p.player || "Player";
  document.getElementById("cardSubtitle").textContent = [p.team, posRank].filter(Boolean).join(" • ");
  updatePlayerMeta(p);
  document.getElementById("cardMyRank").textContent = "#" + myRank;
  renderSourceComparison(p, myRank);

  updateRiskMeter(p.tier);
  updatePlayerStats(p);
  renderPlayerPhoto(p);

  document.getElementById("playerModal").classList.add("open");
  document.getElementById("playerModal").setAttribute("aria-hidden","false");
  document.body.classList.add("modal-open");
}

function closePlayerCard() {
  currentCardIndex = null;
  document.getElementById("playerModal").classList.remove("open");
  document.getElementById("playerModal").setAttribute("aria-hidden","true");
  document.body.classList.remove("modal-open");
}

