function navigateSitePage(){
  const target=(sitePage==='draft'||sitePage==='rankings'||sitePage==='games'||sitePage==='leaderboard'||sitePage==='admin'||sitePage==='pass'||sitePage==='shop'||sitePage==='locker'||sitePage==='album'||sitePage==='home')
    ?sitePage:'rankings';
  openFootballHQSection(target);
}

function syncFootballHQPageChrome(section){
  section=String(section||sitePage||'home').toLowerCase();
  const title=document.getElementById('pageTitle');
  const instructions=document.getElementById('instructionsBar');

  if(section==='draft'){
    if(title)title.textContent='Fantasy Football Draft Simulator';
    if(instructions)instructions.textContent='Build your room, choose your settings, and draft your team.';
  }else if(section==='rankings'){
    if(title)title.textContent='Fantasy Football Rankings';
    if(instructions)instructions.textContent='Explore Football HQ Fantasy Football Rankings. Search by player, team, or position.';
  }
  document.title=section==='draft'?'Fantasy Football Draft Simulator | Football HQ':
    section==='rankings'?'Fantasy Football Rankings | Football HQ':
    section==='games'?'Games | Football HQ':
    section==='leaderboard'?'Leaderboard | Football HQ':
    section==='pass'?'HQ Pass | Football HQ':
    section==='shop'?'HQ Shop | Football HQ':
    section==='locker'?'Locker | Football HQ':
    section==='album'?'HQ Collections | Football HQ':
    section==='admin'?'Database Health | Football HQ':'Football HQ';
}

function applyPageLayout() {
  if(!isEditorMode && !["draft","rankings"].includes(sitePage))return;
  const isDraftPage = sitePage === "draft" && !isEditorMode;
  const isRankingsPage = sitePage === "rankings" && !isEditorMode;

  document.body.classList.toggle("draft-page", isDraftPage);
  document.body.classList.toggle("rankings-page", isRankingsPage);
  document.body.classList.toggle("sim-running", isDraftPage && (simulatorActive || draftModeActive));

  const title = document.getElementById("pageTitle");
  const note = document.getElementById("draftPageTitleNote");
  const nav = document.getElementById("pageNavButton");

  syncFootballHQPageChrome(isDraftPage?'draft':'rankings');
  if (note) note.style.display = "none";
  if (nav) {
    nav.textContent = isDraftPage ? "← RANKINGS" : "DRAFT →";
    nav.style.display = "none";
  }

  const rankingsStandalone=document.getElementById('rankingsStandalone');
  if(rankingsStandalone)rankingsStandalone.style.display=isRankingsPage?'block':'none';

  const tabsShell = document.getElementById("draftTabsShell");
  if (tabsShell) tabsShell.style.display = isDraftPage && draftFlowStage==="live" ? "block" : "none";

  const tabNav = tabsShell ? tabsShell.querySelector(".draft-tab-nav") : null;
  if (tabNav) tabNav.style.display = (isDraftPage&&draftFlowStage==="live") ? "" : "none";

  // V22 draft pages are staged: choice -> settings -> waiting room -> live draft.
  if (!isDraftPage) {
    ["draftLanding","simSetup","draftWaitingRoom","draftControls","simRoom","draftChatPanel"].forEach(function(id){
      const el=document.getElementById(id);if(el)el.style.display="none";
    });
  } else if (typeof renderDraftFlowStage === "function") {
    renderDraftFlowStage();
  }

  const playersPanel = document.getElementById("draftTabPlayers");
  const boardPanel = document.getElementById("draftTabBoard");
  const rosterPanelTab = document.getElementById("draftTabRoster");

  if (isRankingsPage) {
    if (playersPanel) playersPanel.classList.remove("active");
    if (boardPanel) boardPanel.classList.remove("active");
    if (rosterPanelTab) rosterPanelTab.classList.remove("active");
    if(simulatorActive)updatePauseDraftUI();
  } else if (draftFlowStage==="live" && typeof switchDraftTab === "function") {
    switchDraftTab(activeDraftTab || "players");
  }
}


