  const btn=document.getElementById("chatToggleBtn");
  if(!chat)return;
  const open=typeof force==="boolean"?force:!chat.classList.contains("open");
  chat.classList.toggle("open",open);
  if(btn)btn.textContent=open?"CLOSE CHAT":"OPEN CHAT";
