function tone(freq,duration,delay,volume){
  if(!soundEnabled)return;
  try{ audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)(); const o=audioContext.createOscillator(),g=audioContext.createGain(); o.type='sine';o.frequency.value=freq;g.gain.value=volume||.06;o.connect(g);g.connect(audioContext.destination);const t=audioContext.currentTime+(delay||0);o.start(t);o.stop(t+(duration||.12)); }catch(e){}
}
function playDraftSound(type){
  if(!soundEnabled)return;
  if(type==='clock'){tone(660,.13,0,.075);tone(880,.18,.15,.075);} else if(type==='warning'){tone(760,.07,0,.09);tone(520,.08,.075,.08);} else if(type==='sniped'){tone(260,.15,0,.07);tone(190,.22,.13,.07);} else {tone(520,.09,0,.055);tone(700,.1,.1,.055);}
}
function maybePlayDraftSounds(){
  if(!simulatorActive)return;
  const info=getSnakeInfo(simulatorOverallPick); const myTurn=Number(info.teamSlot)===Number(simulatorUserSlot);
  const marker=String(simulatorOverallPick)+':'+String(info.teamSlot);
  if(myTurn && marker!==lastOnClockSoundMarker){ lastOnClockSoundMarker=marker; playDraftSound('clock'); }
  if(simulatorPickLog.length>lastPickSoundCount){
    const newPicks=simulatorPickLog.slice(lastPickSoundCount); lastPickSoundCount=simulatorPickLog.length;
    newPicks.forEach(function(p){ if(playerQueue.indexOf(p.key)>=0 && Number(p.teamSlot)!==Number(simulatorUserSlot)) playDraftSound('sniped'); else playDraftSound('pick'); });
    renderPlayerQueue();
  }
  if(myTurn && userClockSeconds<=10 && userClockSeconds>0 && userClockSeconds!==lastClockWarningSecond){ lastClockWarningSecond=userClockSeconds; playDraftSound('warning'); }
  if(!myTurn || userClockSeconds>10) lastClockWarningSecond=-1;
}
function renderDraftChat(state){
  const panel=document.getElementById('draftChatPanel'), box=document.getElementById('draftChatMessages');
  if(!panel||!box)return;
  if(draftOpponentMode!=='online'){renderLocalDraftChat();return;}
  const open=!!onlineRoomCode;if(!open)return;
  const messages=(state&&state.chat)||[];
  if(!messages.length){box.innerHTML='<div class="chat-empty">No messages yet. Start the trash talk.</div>';return;}
  const wasNearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<45;
  box.innerHTML=messages.map(function(m){const d=new Date(Number(m.at)||Date.now());return '<div class="chat-message"><span class="chat-name">'+escapeHTML(m.name||'Manager')+'</span><span class="chat-text">'+escapeHTML(m.text||'')+'</span><span class="chat-time">'+d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})+'</span></div>';}).join('');
  if(wasNearBottom||messages.length!==lastChatMessageCount)box.scrollTop=box.scrollHeight;
  lastChatMessageCount=messages.length;
}


const FHQ_BLOCKED_CHAT_WORDS=['fuck','fucking','fucked','fucker','shit','shitty','bitch','bitches','asshole','dick','cunt','motherfucker','motherfucking','bastard','slut','whore','retard','retarded'];

function filterFootballHQChat(text){
  let out=String(text||'');
  FHQ_BLOCKED_CHAT_WORDS.slice().sort((a,b)=>b.length-a.length).forEach(function(word){
    const safe=word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    out=out.replace(new RegExp('(^|[^a-z0-9])('+safe+')(?=$|[^a-z0-9])','gi'),function(_,pre){
      return pre+'***';
    });
  });
  return out;
}

const FHQ_LOCAL_CHAT_KEY='footballHQLocalDraftChatV2';

function fhqReadLocalDraftChat(){
  try{
    const parsed=JSON.parse(localStorage.getItem(FHQ_LOCAL_CHAT_KEY)||'[]');
    return Array.isArray(parsed)?parsed:[];
  }catch(e){
    console.warn('Football HQ chat read failed',e);
    return [];
  }
}

function fhqWriteLocalDraftChat(messages){
  const clean=Array.isArray(messages)?messages.slice(-100):[];
  try{
    localStorage.setItem(FHQ_LOCAL_CHAT_KEY,JSON.stringify(clean));
  }catch(e){
    console.warn('Football HQ chat save failed',e);
  }
  localDraftChatMessages=clean.slice();
  return clean;
}

function fhqSetChatStatus(message,isError){
  const status=document.getElementById('draftChatSaveStatus');
  if(!status)return;
  status.textContent=String(message||'');
  status.style.color=isError?'#ff7777':'#77c999';
  clearTimeout(fhqSetChatStatus._timer);
  if(message){
    fhqSetChatStatus._timer=setTimeout(function(){
      if(status)status.textContent='';
    },1400);
  }
}

function fhqBuildChatRow(message){
  const row=document.createElement('div');
  row.className='chat-message';

  const name=document.createElement('span');
  name.className='chat-name';
  name.textContent=String(message.name||'You');

  const body=document.createElement('span');
  body.className='chat-text';
  body.textContent=String(message.text||'');

  const time=document.createElement('span');
  time.className='chat-time';
  const d=new Date(Number(message.at)||Date.now());
  time.textContent=d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});

  row.appendChild(name);
  row.appendChild(body);
  row.appendChild(time);
  return row;
}

function renderLocalDraftChat(){
  const box=document.getElementById('draftChatMessages');
  const modeLabel=document.getElementById('draftChatMode');

  if(modeLabel)modeLabel.textContent=draftOpponentMode==='online'?'Private room chat':'This draft only';
  if(!box||draftOpponentMode==='online')return;

  const messages=fhqReadLocalDraftChat();
  localDraftChatMessages=messages.slice();

  box.innerHTML='';

  if(!messages.length){
    const empty=document.createElement('div');
    empty.className='chat-empty';
    empty.textContent='No messages yet. Say something to your draft room.';
    box.appendChild(empty);
    return;
  }

  messages.forEach(function(message){
    box.appendChild(fhqBuildChatRow(message));
  });
  box.scrollTop=box.scrollHeight;
}

function fhqAppendLocalChatMessage(message){
  const box=document.getElementById('draftChatMessages');
  if(!box||!message)return;
  const empty=box.querySelector('.chat-empty');
  if(empty)empty.remove();
  box.appendChild(fhqBuildChatRow(message));
  box.scrollTop=box.scrollHeight;
}

function fhqShowChatSent(){
  fhqSetChatStatus('Message sent',false);
}

function sendDraftChatMessage(){
  const input=document.getElementById('draftChatInput');
  if(!input)return false;

  const raw=String(input.value||'').trim().slice(0,220);
  if(!raw)return false;

  const message=filterFootballHQChat(raw);

  if(draftOpponentMode!=='online'){
    const item={
      id:'m-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),
      name:fhqGetUsername()||'You',
      text:message,
      at:Date.now()
    };

    const messages=fhqReadLocalDraftChat();
    messages.push(item);
    const saved=fhqWriteLocalDraftChat(messages);

    /* Verify the write before clearing what the user typed. */
    const verified=saved.some(function(m){return m&&m.id===item.id;});
    if(!verified){
      fhqSetChatStatus('Message could not be saved. Try again.',true);
      return false;
    }

    input.value='';

    const panel=document.getElementById('draftChatPanel');
    if(panel)panel.classList.add('open');
    const btn=document.getElementById('chatToggleBtn');
    if(btn)btn.textContent='CLOSE CHAT';

    /* Paint immediately from the verified saved record. */
    renderLocalDraftChat();
    fhqShowChatSent();
    return true;
  }

  if(!onlineRoomCode||!onlineMemberToken){
    fhqSetChatStatus('Join or create the Private Room before sending chat.',true);
    return false;
  }

  google.script.run
    .withSuccessHandler(function(state){
      input.value='';
      applyOnlineRoomState(state);
      fhqShowChatSent();
    })
    .withFailureHandler(function(err){
      fhqSetChatStatus((err&&err.message)||'Chat message could not send.',true);
    })
    .postDraftChat(onlineRoomCode,onlineMemberToken,message);

  return true;
}

function fhqSendDraftChatFromUI(){
  return sendDraftChatMessage();
}

