    ARI:"#97233F",ATL:"#A71930",BAL:"#241773",BUF:"#00338D",CAR:"#0085CA",CHI:"#0B162A",
    CIN:"#FB4F14",CLE:"#FF3C00",DAL:"#003594",DEN:"#FB4F14",DET:"#0076B6",GB:"#203731",
    HOU:"#03202F",IND:"#002C5F",JAX:"#006778",KC:"#E31837",LV:"#A5ACAF",LAC:"#0080C6",
