function updateSimulatorRoom() {
  const room = document.getElementById("simRoom");
  const title = document.getElementById("clockTitle");
  const subtitle = document.getElementById("clockSubtitle");
  const clock = document.getElementById("draftClock");
  const progress = document.getElementById("simProgress");
  const setup = document.getElementById("simSetup");
  const manualBtn = document.getElementById("draftModeBtn");
  const simStartBtn = document.getElementById("simStartBtn");

  if (setup) setup.style.display = simulatorActive ? "none" : "";
  if (manualBtn) manualBtn.style.display = simulatorActive ? "none" : "";
  if (simStartBtn) simStartBtn.style.display = simulatorActive || draftOpponentMode === "online" ? "none" : "inline-block";

  if (room) room.classList.toggle("open", simulatorActive || simulatorPickLog.length > 0);
  renderRecentPicks();
  renderDraftAssist();
  updateDraftTurnRibbon();
  updateDraftResumeNote();
  maybePlayDraftSounds();

  if (!simulatorActive) {
    const clockPanel=document.querySelector("#simRoom .clock-panel");if(clockPanel)clockPanel.classList.remove("danger");
    if (title) title.textContent = simulatorPickLog.length ? "Draft Complete / Paused" : "Fantasy Football Draft Simulator";
    if (subtitle) subtitle.textContent = simulatorPickLog.length ? simulatorPickLog.length + " picks recorded" : "";
    if (clock) {
      clock.textContent = "--";
      clock.className = "draft-clock waiting";
    }
  } else {
    const info = getSnakeInfo(simulatorOverallPick);

    if (simulatorIsHumanTurn()) {
      const clockPanel = document.querySelector("#simRoom .clock-panel");
      if (clockPanel) {
        clockPanel.classList.add("you-are-up");
        clockPanel.classList.toggle("danger", !!pickTimerSeconds && userClockSeconds<=10 && userClockSeconds>0);
      }
      const manager = getManagerNameForSlot(info.teamSlot);
      const isThisDevice = draftOpponentMode !== "online" || Number(info.teamSlot) === Number(simulatorUserSlot);
      if (title) title.textContent = "🟢 " + (Number(info.teamSlot) === Number(simulatorUserSlot) ? "YOU'RE" : manager.toUpperCase() + " IS") + " ON THE CLOCK — Pick " + info.label;
      if (subtitle) subtitle.textContent = draftOpponentMode === "online" && !isThisDevice
        ? "Waiting for " + manager + " to make a pick on their device."
        : "Choose any available player. At 0:00 the host will make a value-based auto-pick.";
      if (clock) {
        clock.textContent = pickTimerSeconds ? String(Math.max(0, userClockSeconds)).padStart(2, "0") : "∞";
        clock.className = "draft-clock" + (userClockSeconds <= 10 ? " warning" : "");
      }
    } else {
      const clockPanel = document.querySelector("#simRoom .clock-panel");
      if (clockPanel) {clockPanel.classList.remove("you-are-up");clockPanel.classList.remove("danger");}
      if (title) title.innerHTML = "CPU " + info.teamSlot + " is picking <span class=\"cpu-thinking\">•••</span>";
      if (subtitle) subtitle.textContent = "Next pick: " + info.label + " • Your draft slot: " + simulatorUserSlot;
      if (clock) {
        clock.textContent = "CPU";
        clock.className = "draft-clock waiting";
      }
    }
  }

  if (progress) {
    const total = simulatorTeams * simulatorRounds;
    const completed = Math.min(simulatorPickLog.length, total);
    const round = simulatorActive && simulatorOverallPick <= total ? getSnakeInfo(simulatorOverallPick).round : simulatorRounds;
    progress.innerHTML =
      '<strong>' + simulatorTeams + '-team snake</strong><br>' +
      'Your slot: <strong>' + simulatorUserSlot + '</strong><br>' +
      'Round: <strong>' + round + ' / ' + simulatorRounds + '</strong><br>' +
      'Picks complete: <strong>' + completed + ' / ' + total + '</strong><br>' +
      'Your roster: <strong>' + myRoster.size + '</strong><br>' +
      ((draftOpponentMode === "friends" || draftOpponentMode === "online")
        ? 'Humans: <strong>' + Object.keys(humanManagers).length + '</strong> • CPU fill: <strong>' + Math.max(0, simulatorTeams - Object.keys(humanManagers).length) + '</strong>' +
          (draftOpponentMode === "online" && onlineRoomCode ? '<br>Room: <strong>' + escapeHTML(onlineRoomCode) + '</strong>' : '')
        : 'CPU model: <strong>Market-aware</strong>');
  }
}


function toggleAutoDraft() {
  if (sitePage !== "draft" || isEditorMode) return;

  autoDraftEnabled = !autoDraftEnabled;
  updateDraftUI();

  /*
    If Auto Draft is turned on while you are already on the clock,
    make the pick immediately and keep the snake draft moving.
  */
  if (autoDraftEnabled && simulatorActive && simulatorIsUserTurn() && !simulatorBusy) {
    clearUserClock();
    autoDraftUserPick();
  }
}

function autoDraftUserPick() {
  if (!simulatorActive || !simulatorIsUserTurn()) return;

  const entry = chooseUserAutoPick();
  if (!entry) {
    finishSimulator();
    return;
  }

  const info = getSnakeInfo(simulatorOverallPick);
  recordSimulatorPick(entry, simulatorUserSlot, true, true);
  showSimMessage("🤖 Auto Draft selected " + entry.player.player + " for you at " + info.label + ".");
  updateDraftUI();
  renderPlayers(document.getElementById("searchInput").value);
  continueSimulator();
}


let activeDraftTab = "players";

function switchDraftTab(tabName) {
  const allowed = ["players","board","roster"];
  activeDraftTab = allowed.includes(tabName) ? tabName : "players";

  document.querySelectorAll(".draft-tab-button").forEach(button => {
    button.classList.toggle("active", button.dataset.tab === activeDraftTab);
  });

  document.querySelectorAll(".draft-tab-panel").forEach(panel => {
    panel.classList.remove("active");
  });

  const panel = document.getElementById(
    activeDraftTab === "players" ? "draftTabPlayers" :
    activeDraftTab === "board" ? "draftTabBoard" :
    "draftTabRoster"
  );

  if (panel) panel.classList.add("active");

  if (activeDraftTab === "board") {
    renderFullDraftBoard();
  } else if (activeDraftTab === "roster") {
    renderRoster(true);
  }
}

function renderFullDraftBoard() {
  const root = document.getElementById("fullDraftBoard");
  const count = document.getElementById("boardPickCount");
  if (!root) return;

  const teams = Number(simulatorTeams) || 12;
  const rounds = Number(simulatorRounds) || 13;
  const structureKey = teams + "x" + rounds + "-slot" + simulatorUserSlot + "-mode" + draftOpponentMode + "-humans" + JSON.stringify(humanManagers);

  if (count) {
    count.textContent = simulatorPickLog.length + " pick" + (simulatorPickLog.length === 1 ? "" : "s");
  }

  /*
    Build the board grid only when the league setup changes. Previously the entire
    board (including every player photo) was replaced after every CPU pick, which
    caused the visible flashing/glitching during fast drafts.
  */
  if (root.dataset.boardStructure !== structureKey) {
    let scaffold = '<div class="board-grid" style="grid-template-columns:58px repeat(' + teams + ', minmax(92px,1fr));">';
    scaffold += '<div></div>';

    for (let team = 1; team <= teams; team++) {
      const label = team === simulatorUserSlot ? "MY TEAM" : (humanManagers[team] || ("TEAM " + team));
      scaffold += '<div class="board-team-header">' + escapeHTML(label) + '</div>';
    }

    for (let round = 1; round <= rounds; round++) {
      scaffold += '<div class="board-round-label">R' + round + '</div>';
      for (let team = 1; team <= teams; team++) {
        const pickInRound = round % 2 === 1 ? team : (teams - team + 1);
        const overallPick = ((round - 1) * teams) + pickInRound;
        scaffold += '<div id="boardPickCell-' + overallPick + '" class="board-pick-cell empty" data-pick-signature="">' +
          '<div class="board-pick-num">' + round + '.' + String(pickInRound).padStart(2,"0") + '</div>' +
          '<div class="board-player-meta">—</div></div>';
      }
    }

    scaffold += '</div>';
    root.innerHTML = scaffold;
    root.dataset.boardStructure = structureKey;
  }

  const pickMap = {};
  simulatorPickLog.forEach(function(pick) {
    if (pick) pickMap[pick.overallPick] = pick;
  });

  const playerByKey = {};
  players.forEach(function(player) {
    playerByKey[normalizePlayerName(player.player)] = player;
  });

  const total = teams * rounds;
  for (let overallPick = 1; overallPick <= total; overallPick++) {
    const cell = document.getElementById("boardPickCell-" + overallPick);
    if (!cell) continue;

    const pick = pickMap[overallPick];
    if (!pick) {
      const info = getSnakeInfo(overallPick);
      const isCurrent=simulatorActive&&Number(overallPick)===Number(simulatorOverallPick);
      const isUpcomingMine=Number(info.teamSlot)===Number(simulatorUserSlot)&&overallPick>=simulatorOverallPick;
      cell.className="board-pick-cell empty"+(isCurrent?" current-pick":"")+(isUpcomingMine?" upcoming-mine":"");
      if(cell.dataset.pickSignature!==""){
        cell.innerHTML=
          '<div class="board-pick-num">'+escapeHTML(info.label||"")+'</div>'+
          '<div class="board-player-meta">—</div>';
        cell.dataset.pickSignature="";
      }
      continue;
    }

    const signature = [
      pick.key || "",
      pick.name || "",
      pick.position || "",
      pick.team || "",
      pick.mine ? "1" : "0",
      pick.pickLabel || ""
    ].join("|");

    // Existing drafted cells stay completely untouched, so their photos never reload.
    if (cell.dataset.pickSignature === signature) continue;

    const player = playerByKey[pick.key] || {
      player: pick.name || "Player",
      position: pick.position || "",
      team: pick.team || ""
    };
    const nflTeam = String(player.team || pick.team || "").toUpperCase();

    cell.className = "board-pick-cell has-team-accent" + (pick.mine ? " mine" : "");
    cell.style.setProperty("--team-accent",draftTeamAccent(nflTeam));
    cell.innerHTML =
      '<div class="board-pick-num">' + escapeHTML(pick.pickLabel || "") + '</div>' +
      '<div class="board-pick-main">' +
        draftedPlayerPhotoHTML(player, "draft-player-photo-board") +
        '<div class="board-pick-text">' +
          '<div class="board-player-name">' + escapeHTML(pick.name || player.player || "Player") + '</div>' +
          '<div class="board-player-meta">' +
            teamLogoHTML(nflTeam) +
            '<span>' + escapeHTML((pick.position || player.position || "") + (nflTeam ? " • " + nflTeam : "") + (isHumanTeamSlot(pick.teamSlot) ? " • " + (pick.mine ? "MY TEAM" : getManagerNameForSlot(pick.teamSlot)) : "")) + '</span>' +
          '</div>' +
        '</div>' +
      '</div>';
    cell.dataset.pickSignature = signature;
  }
}


function updateDraftUI() {
  const draftBtn = document.getElementById("draftModeBtn");
  const autoBtn = document.getElementById("autoDraftBtn");
  const resetBtn = document.getElementById("resetDraftBtn");
  const status = document.getElementById("draftStatus");
  const draftHeader = document.getElementById("draftHeader");

  if (status) status.textContent = draftedPlayers.size + " drafted • " + myRoster.size + " mine";

  if (draftBtn) {
    draftBtn.textContent = draftModeActive ? "🏈 MANUAL DRAFT ACTIVE" : "MANUAL DRAFT MODE";
    draftBtn.classList.toggle("active", draftModeActive && !simulatorActive);
  }

  if (autoBtn) {
    autoBtn.style.display = (simulatorActive && draftOpponentMode === "cpu") ? "inline-block" : "none";
    autoBtn.textContent = autoDraftEnabled ? "ON" : "OFF";
    autoBtn.classList.toggle("active", autoDraftEnabled);
  }

  if (resetBtn) resetBtn.style.display = draftModeActive ? "inline-block" : "none";

  if (draftHeader) {
    draftHeader.classList.toggle("draft-hidden", !draftModeActive || isEditorMode);
    draftHeader.textContent = simulatorActive ? ((draftOpponentMode === "friends" || draftOpponentMode === "online") ? "Current Pick" : "Your Pick") : "Draft Action";
  }

  renderRoster();
  updateSimulatorRoom();
  renderFullDraftBoard();

  const topFormat = document.getElementById("topDraftFormat");
  const topRound = document.getElementById("topDraftRound");
  const topPicks = document.getElementById("topDraftPicks");
  const topRoster = document.getElementById("topDraftRoster");

  if (topFormat) topFormat.textContent = simulatorTeams + "-team snake";
  if (topRound) {
    const currentRound = simulatorActive && simulatorOverallPick <= simulatorTeams * simulatorRounds
      ? getSnakeInfo(simulatorOverallPick).round
      : Math.min(simulatorRounds, Math.max(1, Math.ceil(Math.max(1, simulatorPickLog.length) / simulatorTeams)));
    topRound.textContent = currentRound + " / " + simulatorRounds;
  }
  if (topPicks) topPicks.textContent = simulatorPickLog.length;
  if (topRoster) topRoster.textContent = myRoster.size;

  applyPageLayout();
}

function toggleDraftMode() {
  if (sitePage !== "draft" || isEditorMode || simulatorActive) return;
  draftModeActive = !draftModeActive;
  updateDraftUI();
  renderPlayers(document.getElementById("searchInput").value);
  toggleDraftToolsMenu(false);
  toggleDraftChat(false);
  draftFlowStage="choice";
  renderDraftFlowStage();
}

function markDrafted(event, index, mine) {
  event.stopPropagation();
  if (!draftModeActive || isEditorMode) return;

  const player = players[index];
  if (!player) return;

  const key = normalizePlayerName(player.player);
  if (!key || draftedPlayers.has(key)) return;

  /* Online rooms only allow this device to draft for its own slot. */
  if (simulatorActive && draftOpponentMode === "online") {
    if (!onlineIsMyTurn()) return;
    submitOnlinePlayerPick(index);
    return;
  }

  /* In same-device simulated drafts, any configured human manager can make the current pick. */
  if (simulatorActive) {
    if (!simulatorIsHumanTurn() || simulatorBusy) return;

    clearUserClock();
    const info = getSnakeInfo(simulatorOverallPick);
    const isMine = info.teamSlot === simulatorUserSlot;
    const entry = {player:player, index:index, key:key};
    recordSimulatorPick(entry, info.teamSlot, isMine, false);
    showSimMessage("");
    updateDraftUI();
    renderPlayers(document.getElementById("searchInput").value);
    continueSimulator();
    return;
  }

  draftedPlayers.add(key);
  if (mine) myRoster.add(key);
  draftHistory.push({key:key, mine:!!mine});
  saveDraftState();
  updateDraftUI();
  renderPlayers(document.getElementById("searchInput").value);
}

function resetDraft() {
  if (draftOpponentMode === "online" && onlineRoomCode) {
    alert("Private room drafts are shared. Start a new room instead of resetting this one locally.");
    return;
  }
  if (draftedPlayers.size && !confirm("Reset the draft and make every player available again?")) return;

  clearUserClock();
  clearCpuTimer();

  draftedPlayers.clear();
  myRoster.clear();
  draftHistory = [];
  simulatorPickLog = [];
  cpuRosters = {};
  simulatorOverallPick = 1;
  simulatorActive = false;
  simulatorBusy = false;
  autoDraftEnabled = false;
  draftModeActive = false;
  currentPositionFilter = "all";
  showSimMessage("");
  saveDraftState();

  document.querySelectorAll(".filter-btn").forEach(button => {
    button.classList.toggle("active-filter", button.dataset.position === "all");
  });

  updateDraftUI();
  renderPlayers(document.getElementById("searchInput").value);
  toggleDraftToolsMenu(false);
  toggleDraftChat(false);
  draftFlowStage="choice";
  renderDraftFlowStage();
}

function filterPosition(position, clickedButton) {
  currentPositionFilter = String(position || "all").toLowerCase();

  document.querySelectorAll(".filter-btn").forEach(function(button){
    button.classList.toggle("active-filter",String(button.dataset.position||'').toLowerCase()===currentPositionFilter);
  });

  selectedIndex = null;
  const query=sitePage==='draft'?((document.getElementById('draftPlayerSearchInput')||{}).value||''):((document.getElementById("searchInput")||{}).value||'');
  renderPlayers(query);
}

function calculatePositionRanks() {
  const counts = {};
  return players.map(player => {
    const position = String(player.position || "").trim().toUpperCase();
    counts[position] = (counts[position] || 0) + 1;
    return position ? `${position}${counts[position]}` : "—";
  });
}


