let fhqRankingsSort={key:'hq',direction:'asc'};
function fhqConsensusRankMap(){
  const rows=(Array.isArray(players)?players:[]).map(function(p,index){
    const c=comparisonSummary(p);
    const raw=c&&c.consensus;
    const score=(raw!==null&&raw!==undefined&&raw!==''&&Number(raw)>0&&Number.isFinite(Number(raw)))?Number(raw):null;
    return {key:normalizePlayerName(p.player),score:score,hq:index+1};
  }).filter(function(r){return r.score!==null});
  rows.sort((a,b)=>a.score-b.score||a.hq-b.hq||a.key.localeCompare(b.key));
  const map=new Map();rows.forEach((r,i)=>map.set(r.key,i+1));return map;
}
function fhqSetRankingsSort(key){
  key=key==='consensus'?'consensus':'hq';
  if(fhqRankingsSort.key===key)fhqRankingsSort.direction=fhqRankingsSort.direction==='asc'?'desc':'asc';
  else{fhqRankingsSort.key=key;fhqRankingsSort.direction='asc'}
  document.querySelectorAll('[data-rank-sort]').forEach(function(b){
    const active=b.dataset.rankSort===fhqRankingsSort.key;b.classList.toggle('active',active);
    const a=b.querySelector('.fhq-sort-arrow');if(a)a.textContent=active?(fhqRankingsSort.direction==='asc'?'↑':'↓'):'↕';
  });
  renderPlayers((document.getElementById('searchInput')||{}).value||'');
}
function renderPlayers(filter = "") {
  if(!isEditorMode && sitePage==='draft'){
    const draftInput=document.getElementById('draftPlayerSearchInput');
    filter=draftInput?String(draftInput.value||''):String(fhqDraftPlayerSearchValue||filter||'');
    fhqDraftPlayerSearchValue=filter;
  }
  const targetId = (!isEditorMode && sitePage==='draft') ? 'draftRankingsBody' : 'rankingsBody';
  const tableBody = document.getElementById(targetId);
  if (!tableBody) return;
  if (!Array.isArray(players)) players = [];
  if (!players.length && !masterRankingsLoaded) {
    tableBody.innerHTML = '<tr><td colspan="'+((!isEditorMode&&sitePage==="rankings")?8:7)+'" style="text-align:center;padding:28px;color:#9aa1a7;font-weight:800">Loading saved rankings…</td></tr>';
    return;
  }
  if (!players.length && masterRankingsLoaded) players = JSON.parse(JSON.stringify(starterPlayers));
  const positionRanks = calculatePositionRanks();
  const consensusRankMap=fhqConsensusRankMap();
  tableBody.innerHTML = "";

  let fhqRenderEntries=players.map((player,index)=>({player,index}));
  const publicRankings=!isEditorMode&&sitePage==='rankings'&&targetId==='rankingsBody';
  if(publicRankings){
    const dir=fhqRankingsSort.direction==='desc'?-1:1;
    fhqRenderEntries.sort(function(a,b){
      if(fhqRankingsSort.key==='consensus'){
        const ar=consensusRankMap.get(normalizePlayerName(a.player.player));
        const br=consensusRankMap.get(normalizePlayerName(b.player.player));
        const aMissing=!Number.isFinite(Number(ar)),bMissing=!Number.isFinite(Number(br));
        if(aMissing!==bMissing)return aMissing?1:-1;
        if(aMissing&&bMissing)return a.index-b.index;
        return dir*(Number(ar)-Number(br));
      }
      return dir*(a.index-b.index);
    });
  }

  fhqRenderEntries.forEach(({player,index}) => {
    const position = String(player.position || "").trim().toUpperCase();
    const positionalRank = positionRanks[index];
    const playerKey = normalizePlayerName(player.player);
    const comparison = comparisonSummary(player);
    const searchableText = `${player.player} ${position} ${positionalRank} ${player.team} ${fhqTeamSearchText(player.team)} ${player.tier} ${player.notes}`.toLowerCase();

    if (!searchableText.includes(filter.toLowerCase())) return;
    if (currentPositionFilter !== "all" && position.toLowerCase() !== currentPositionFilter) return;
    if (!isEditorMode && sitePage === "draft" && draftModeActive && draftedPlayers.has(playerKey)) return;

    const row = document.createElement("tr");
    row.dataset.index = index;
    row.dataset.playerKey = playerKey;
    row.classList.add(`pos-${position.toLowerCase()}`);
    if (selectedIndex === index) row.classList.add("selected");
    if (myGuys.has(playerKey)) row.classList.add("my-guy-row");

    const badgeClass = ["RB", "WR", "QB", "TE"].includes(position) ? position.toLowerCase() : "other";
    const editable = isEditorMode ? 'contenteditable="true"' : '';
    const removeCell = isEditorMode
      ? `<td><button type="button" class="delete-button" onclick="deletePlayer(event, ${index})">X</button></td>`
      : `<td style="display:none"></td>`;

    const isPublicRankingsRow = (!isEditorMode && targetId === 'rankingsBody');
    const myGuyCell = isPublicRankingsRow
      ? `<td class="my-guys-col"><button type="button" class="my-guys-btn ${myGuys.has(playerKey) ? "active" : ""}" aria-label="Toggle My Guy" title="${myGuys.has(playerKey) ? "Remove from My Guys" : "Add to My Guys"}" onclick="toggleMyGuy(event, '${playerKey}')">${myGuys.has(playerKey) ? "★" : "☆"}</button></td>`
      : "";

    let draftCell = `<td class="draft-column draft-hidden"></td>`;

    if (!isEditorMode && sitePage === 'draft' && draftModeActive) {
      if (simulatorActive) {
        const canDraftHere = draftOpponentMode === "online" ? onlineIsMyTurn() : simulatorIsHumanTurn();
        draftCell = canDraftHere
          ? `<td class="draft-column"><button type="button" class="sim-pick-button" onclick="markDrafted(event, ${index}, true)">DRAFT</button></td>`
          : `<td class="draft-column"><button type="button" class="sim-wait-button" disabled>WAIT</button></td>`;
      } else {
        draftCell = `<td class="draft-column"><div class="draft-action-wrap"><button type="button" class="my-team-button" onclick="markDrafted(event, ${index}, true)">MY TEAM</button><button type="button" class="other-draft-button" onclick="markDrafted(event, ${index}, false)">DRAFTED</button></div></td>`;
      }
    }

    row.innerHTML = `
      <td class="rank">${index + 1}</td>
      <td ${editable} data-field="player"><div class="player-name-cell">${!isEditorMode && sitePage === "draft" ? `<button type="button" class="queue-star ${playerQueue.indexOf(playerKey)>=0 ? "queued" : ""}" aria-label="Toggle queue" title="Draft Queue" onclick="toggleQueue(event, '${playerKey}')">${playerQueue.indexOf(playerKey)>=0 ? '★' : '☆'}</button>` : ""}${teamLogoHTML(player.team)}<span>${escapeHTML(player.player)}</span></div></td>
      ${myGuyCell}
      <td class="position"><span class="position-badge ${badgeClass}">${escapeHTML(positionalRank)}</span></td>
      <td ${editable} class="team" data-field="team">${
        isEditorMode ? escapeHTML(player.team) : teamBadgeHTML(player.team)
      }</td>
      <td class="consensus-only consensus-col"><span class="consensus-value unique">${consensusRankMap.has(playerKey)?'#'+consensusRankMap.get(playerKey):'N/A'}</span></td>
      <td class="consensus-only consensus-col"><span class="consensus-value">#${index + 1}</span></td>
      <td class="tier" data-field="tier">${
        isEditorMode
          ? riskSelectHTML(index, player.tier)
          : '<span class="risk-badge ' + riskClass(player.tier) + '">' + escapeHTML(riskLabel(player.tier)) + '</span>'
      }</td>
      ${draftCell}`;

    if (isEditorMode) {
      row.addEventListener("click", event => {
        if (event.target.tagName === "BUTTON" || event.target.isContentEditable) return;
        selectPlayer(index);
      });

      row.querySelectorAll('[contenteditable="true"]').forEach(cell => {
        cell.addEventListener("input", function() {
          players[index][this.dataset.field] = this.textContent.trim();
        });
      });
      row.querySelectorAll(".risk-select").forEach(select => {
        select.addEventListener("click", event => event.stopPropagation());
        select.addEventListener("change", function(event) {
          event.stopPropagation();
          players[index].tier = this.value;
        });
      });
    } else {
      row.style.cursor = "pointer";
      row.title = "Click for player details";
      row.addEventListener("click", () => openPlayerCard(index));
    }

    tableBody.appendChild(row);
  });

  renderPlayerQueue();
  if (sitePage === "draft") renderDraftAssist();

  const boardStatus = document.getElementById("draftBoardStatus");
  if (boardStatus) {
    boardStatus.textContent = currentPositionFilter !== "all"
      ? "Best available • " + currentPositionFilter.toUpperCase()
      : "Best available players";
  }
  updateFootballHQRankingsStatus();
}

function selectPlayer(index) {
  if (!isEditorMode) return;
  if (selectedIndex === null) { selectedIndex = index; renderPlayers(searchInput.value); return; }
  if (selectedIndex === index) { selectedIndex = null; renderPlayers(searchInput.value); return; }
  [players[selectedIndex], players[index]] = [players[index], players[selectedIndex]];
  selectedIndex = null;
  renderPlayers(searchInput.value);
}

function addPlayer() {
  if (!isEditorMode) return;
  players.push({ player:"New Player", position:"", team:"", tier:"", notes:"" });
  renderPlayers();
}

function deletePlayer(event, index) {
  if (!isEditorMode) return;
  event.stopPropagation();
  const playerName = players[index].player || "this player";
  if (confirm(`Remove ${playerName} from your rankings?`)) {
    players.splice(index,1);
    selectedIndex=null;
    renderPlayers(searchInput.value);
  }
}

function saveRankings() {
  if (!isEditorMode) return;
  const button = document.querySelector('button[onclick="saveRankings()"]');
  const originalText = button.textContent;
  button.disabled = true;
  button.textContent = "Saving...";

  google.script.run
    .withSuccessHandler(function() {
      button.disabled = false;
      button.textContent = originalText;
      alert("Master rankings saved. Public viewers will see this order when they open or refresh the shared link.");
    })
    .withFailureHandler(function(error) {
      button.disabled = false;
      button.textContent = originalText;
      alert("Could not save the master rankings: " + error.message);
    })
    .saveRankings(players, editorKey);
}

function resetRankings() {
  if (!isEditorMode) return;
  if (!confirm("Reset this working copy to the original Top 250? It will not change the public master list until you click Save Rankings.")) return;
  players = JSON.parse(JSON.stringify(starterPlayers));
  selectedIndex = null;
  renderPlayers();
}

function loadMasterRankings() {
  document.body.classList.add('rankings-loading');

  // V69: never leave the public Rankings page blank while Apps Script responds.
  if (!Array.isArray(players) || !players.length) {
    players = JSON.parse(JSON.stringify(starterPlayers));
    masterRankingsLoaded = true;
    renderPlayers((document.getElementById("searchInput") || {}).value || "");
    updateFootballHQRankingsStatus();
  }

  let settled=false;
  const watchdog=setTimeout(function(){
    if(settled)return;
    document.body.classList.remove('rankings-loading');
    fhqTop500Extended=false;
    renderPlayers((document.getElementById("searchInput") || {}).value || "");
    scheduleTop500Extension(100);
    console.warn('Rankings backend is slow; Football HQ is showing the embedded rankings until it responds.');
  },2200);

  google.script.run
    .withSuccessHandler(function(savedPlayers) {
      settled=true;clearTimeout(watchdog);
      masterRankingsLoaded = true;
      if (Array.isArray(savedPlayers) && savedPlayers.length > 0) {
        players = savedPlayers.filter(function(p){ return p && p.player; });
      } else if (!players.length) {
        players = JSON.parse(JSON.stringify(starterPlayers));
      }
      document.body.classList.remove('rankings-loading');
      fhqTop500Extended=false;
      renderPlayers((document.getElementById("searchInput") || {}).value || "");
      loadComparisonRankings();
      scheduleTop500Extension(150);
    })
    .withFailureHandler(function(error) {
      settled=true;clearTimeout(watchdog);
      masterRankingsLoaded = true;
      if (!players.length) players = JSON.parse(JSON.stringify(starterPlayers));
      document.body.classList.remove('rankings-loading');
      fhqTop500Extended=false;
      renderPlayers((document.getElementById("searchInput") || {}).value || "");
      console.warn("Saved rankings could not be loaded; embedded rankings are being used.", error);
      loadComparisonRankings();
      scheduleTop500Extension(150);
    })
    .getRankings();
}

function setMode(editorAllowed) {
  isEditorMode = !!editorAllowed;
  document.body.classList.toggle("editor-mode", isEditorMode);

  document.querySelectorAll(".editor-only").forEach(el => {
    el.style.display = isEditorMode ? "" : "none";
  });

  if (isEditorMode) {
    sitePage = "rankings";
    draftModeActive = false;
    simulatorActive = false;
  }

  const modeLabel = document.getElementById("modeLabel");
  const instructionsBar = document.getElementById("instructionsBar");
  const removeHeader = document.getElementById("removeHeader");
  const notesHeader = document.getElementById("notesHeader");

  if (isEditorMode) {
    modeLabel.style.display = "";
    modeLabel.textContent = "Editor mode";
    instructionsBar.textContent = "Click one player, then click another player to swap their rankings. Click inside any box to edit it.";
    if (removeHeader) removeHeader.style.display = "";
    if (notesHeader) notesHeader.style.display = "";
  } else {
    modeLabel.textContent = "";
    modeLabel.style.display = "none";
    instructionsBar.textContent = "Explore my Rankings. Use the search box to find any player, team, or position.";
    if (removeHeader) removeHeader.style.display = "none";
    if (notesHeader) notesHeader.style.display = "none";
  }

  applyPageLayout();
  updateDraftUI();
  renderPlayers((document.getElementById("searchInput") || {}).value || "");
}

