function drawRoundedRect(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function fitCanvasText(ctx,text,maxWidth,startSize,minSize){let size=startSize;while(size>minSize){ctx.font='900 '+size+'px Arial';if(ctx.measureText(text).width<=maxWidth)break;size-=2;}return size;}
function buildDraftShareCardCanvas(){
  const canvas=document.getElementById('shareCardCanvas')||document.createElement('canvas'); canvas.width=1200;canvas.height=1500;const ctx=canvas.getContext('2d');
  ctx.fillStyle='#0f1215';ctx.fillRect(0,0,1200,1500);
  const grade=calculateDraftGrade(), ranks=calculatePostDraftPowerRankings(), mine=ranks.find(function(t){return t.mine;}), roster=getFinalRosterPlayers();
  ctx.fillStyle='#1b2025';ctx.fillRect(0,0,1200,215);ctx.fillStyle='#fff';ctx.font='900 54px Arial';ctx.fillText('2026 FANTASY DRAFT REPORT',70,92);ctx.fillStyle='#9aa0a6';ctx.font='700 26px Arial';ctx.fillText(simulatorTeams+'-team • Pick '+simulatorUserSlot+' • '+(scoringFormat==='ppr'?'PPR':scoringFormat==='half'?'HALF-PPR':'STANDARD')+' • '+(rosterFormat==='superflex'?'SUPERFLEX':'1QB')+' • '+String(cpuDifficulty).toUpperCase(),70,145);
  drawRoundedRect(ctx,70,250,340,270,24,'#20262b','#343d45');ctx.fillStyle='#9aa0a6';ctx.font='900 23px Arial';ctx.fillText('DRAFT GRADE',105,305);ctx.fillStyle='#fff';ctx.font='1000 118px Arial';ctx.fillText(String(grade.total),100,425);ctx.fillStyle='#6f9ee8';ctx.font='1000 50px Arial';ctx.fillText(grade.letter,295,425);
  drawRoundedRect(ctx,440,250,690,270,24,'#20262b','#343d45');ctx.fillStyle='#9aa0a6';ctx.font='900 23px Arial';ctx.fillText('POST-DRAFT RANK',480,305);ctx.fillStyle='#fff';ctx.font='1000 88px Arial';ctx.fillText(mine?'#'+mine.rank:'—',480,410);ctx.fillStyle='#9aa0a6';ctx.font='800 25px Arial';ctx.fillText(mine?'OF '+ranks.length+' TEAMS':'POWER RANKINGS',485,455);
  ctx.fillStyle='#fff';ctx.font='1000 30px Arial';ctx.fillText('STARTING CORE',70,590);
  const assignments=getMyRosterAssignments().filter(function(x){return x.slot!=='BE';}).slice(0,7);let y=635;
  assignments.forEach(function(item){drawRoundedRect(ctx,70,y,1060,82,14,'#191e22','#303840');ctx.fillStyle='#6f9ee8';ctx.font='1000 24px Arial';ctx.fillText(item.slot,95,y+49);ctx.fillStyle='#fff';ctx.font='900 30px Arial';ctx.fillText(item.name,205,y+50);ctx.fillStyle='#9aa0a6';ctx.font='800 22px Arial';ctx.textAlign='right';ctx.fillText((item.team||'')+' • '+(item.position||''),1090,y+49);ctx.textAlign='left';y+=94;});
  y=Math.max(y+22,1330);ctx.fillStyle='#f4b400';ctx.font='900 22px Arial';ctx.fillText('BEST VALUE',70,y);ctx.fillStyle='#fff';ctx.font='900 28px Arial';ctx.fillText(grade.best?grade.best.pick.name:'—',70,y+40);ctx.fillStyle='#e87171';ctx.font='900 22px Arial';ctx.fillText('BIGGEST REACH',560,y);ctx.fillStyle='#fff';ctx.font='900 28px Arial';ctx.fillText(grade.reach?grade.reach.pick.name:'—',560,y+40);
  ctx.fillStyle='#7f878e';ctx.font='700 21px Arial';ctx.fillText('Fantasy Draft Simulator • Think you can beat this draft?',70,1452);
  const preview=document.getElementById('shareCardPreview');if(preview)preview.classList.add('open');return canvas;
}
async function shareDraftCard(){
  const confirmation=document.getElementById('shareConfirmation');const canvas=buildDraftShareCardCanvas();
  try{
    const blob=await new Promise(function(resolve){canvas.toBlob(resolve,'image/png',.95);});
    const file=new File([blob],'my-2026-fantasy-draft.png',{type:'image/png'});
    if(navigator.canShare && navigator.canShare({files:[file]}) && navigator.share){await navigator.share({title:'My 2026 Fantasy Draft',text:finalRosterShareText(),files:[file]});if(confirmation)confirmation.textContent='Draft card shared!';return;}
    const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='my-2026-fantasy-draft.png';a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},2000);if(confirmation)confirmation.textContent='Draft card image saved — share it anywhere.';
  }catch(err){if(err&&err.name==='AbortError')return;if(confirmation)confirmation.textContent='Could not share the image. Try Share Text instead.';}
}

